-- ============================================================================
-- Exampeak: the DİM Grade 9 question bank, Russian sector. Two papers:
--   12 April 2026, Variant A and 26 April 2026, Variant D (Q5-Q81 of each).
-- ============================================================================
--
-- Generated by scripts/seed-from-sheet.py from Nihad's workbook
-- (Questions_12_and_26_April_2026_ENGLISH_ALL_OPTIONS.xlsm). Do not edit this file by hand:
-- change the workbook or scripts/seed-from-sheet.toml and rerun the script.
--
-- Paste the whole file into the Supabase SQL editor and run it once. It is one
-- transaction: if anything fails, nothing is changed.
--
-- What it does
--   1. Adds written answers marked by the AI marker (migration 0009): the
--      `open-ended` question type and the marker's feedback column.
--   2. Adds `questions.translations` (migration 0010): a question's text in
--      the student's other site language. Maths is stored in English with
--      its Russian wording here, so the Russian site shows it in Russian.
--   3. Loads 143 questions, 70 of them ready for students:
--     12 Apr (A)  English           15 ready,  6 draft
--     12 Apr (A)  Russian Language   0 ready, 30 draft
--     12 Apr (A)  Maths             20 ready,  0 draft
--     26 Apr (D)  English           15 ready,  6 draft
--     26 Apr (D)  Russian Language   0 ready, 30 draft
--     26 Apr (D)  Maths             20 ready,  1 draft
--      A draft is in the bank and on the admin page, but never in a test.
--      supabase/seeds/REVIEW.md says what each draft is waiting for.
--
-- Left out on purpose, and not touched in the database at all:
--   * questions with a picture (12 Apr (A) Q26, Q72, Q77, Q78, Q79, Q81; 26 Apr (D) Q26, Q57, Q73, Q77, Q79). Their diagrams go in
--     through the admin form. The 12 April ones stay image-pending, as the
--     30 Sep maths seed left them.
--   * Q1-Q4 of each paper, the listening questions: there is no audio.
--
-- This supersedes dim-2026-04-12-variant-a/maths-questions.sql. It rewrites
-- the 12 April maths that seed loaded (Q57-Q71, Q73-Q76, Q80): the question
-- text becomes English, with the Russian wording moved into `translations`,
-- and the options and answers are filled in. Don't run the old file again.
--
-- Safe to run again. Each question is matched on its paper and number
-- (`external_ref`), so a second run updates the same rows rather than adding
-- copies. A rerun does put every column below back to what the sheet says,
-- so fix a question in the sheet (or the data file), not only in the admin
-- dashboard. Marks and pictures are never written here and are left alone.
--
-- Requires migrations 0001-0008 (supabase/run-all.sql) to have been run.

begin;

do $$
begin
  if to_regclass('public.questions') is null
     or not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = 'questions'
                      and column_name in ('status'))
     or not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = 'questions'
                      and column_name in ('external_ref')) then
    raise exception 'The questions table, or its status and external_ref columns, are missing. Run supabase/run-all.sql first.';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 1. Migration 0009: written answers
-- ---------------------------------------------------------------------------

-- Exampeak: written answers, marked by an AI marker.
--
-- Run this in the Supabase SQL editor after 0008_question_status.sql.
--
-- ---------------------------------------------------------------------------
-- What changes
-- ---------------------------------------------------------------------------
-- The past papers have questions no exact-match marking can handle: "write a
-- story from these pictures", "explain this expression in your own words".
-- These are `open-ended` questions. The student writes an answer, and an AI
-- marker acting as a Grade 9 teacher marks it against the question's marking
-- guide and says why.
--
-- The marking guide is kept in `correct_answer`, where the other types keep
-- their answer, so everything that copies a question onto an attempt already
-- carries it across. For an open-ended question 0008's rule "a ready question
-- has an answer" therefore reads "a ready question has a marking guide".
--
-- Every statement here is safe to run twice.

-- ---------------------------------------------------------------------------
-- 1. The third question type
-- ---------------------------------------------------------------------------
-- 0001 declared the check inline, so Postgres named it questions_type_check.

alter table questions
  drop constraint if exists questions_type_check;

alter table questions
  add constraint questions_type_check
  check (type in ('multiple-choice', 'short-answer', 'open-ended'));

comment on column questions.correct_answer is
  'The answer text (never the option letter). For open-ended questions, the marking guide: what an answer needs for each mark.';

-- ---------------------------------------------------------------------------
-- 2. What the marker said
-- ---------------------------------------------------------------------------
-- Kept with the answer, so reopening a past result shows the same feedback
-- the student saw, without paying to mark the answer again.
--
-- A written answer the marker could not reach is left with a null score and
-- a null is_correct. Its marks are left out of the paper's total, so a marking
-- outage costs the student nothing rather than counting as a wrong answer.

alter table attempt_questions
  add column if not exists feedback text;

comment on column attempt_questions.feedback is
  'The marker''s feedback on an open-ended answer. Null for other types, and for an answer that could not be marked.';

-- ---------------------------------------------------------------------------
-- 2. Migration 0010: translations
-- ---------------------------------------------------------------------------
-- A question's text in the other site language, shaped
--   { "ru": { "prompt": "...", "options": [...], "correctAnswer": "..." } }
-- `options` is only there when an option reads differently ("8 см³"), in the
-- same order as the question's own; `correctAnswer` only for a short answer
-- that does. The full migration 0010 adds the same column and constraint
-- under the same names, so running both is harmless.

alter table questions
  add column if not exists translations jsonb not null default '{}'::jsonb;

alter table questions
  drop constraint if exists questions_translations_is_object;

alter table questions
  add constraint questions_translations_is_object
  check (jsonb_typeof(translations) = 'object');

-- ---------------------------------------------------------------------------
-- 3. The questions
-- ---------------------------------------------------------------------------

-- Rows from an earlier load of 12 April that predate external_ref: give them
-- one, so the load below updates them instead of adding duplicates.
update questions
set external_ref = 'dim-2026-04-12-variant-a:q' || substring(source from ', Q([0-9]+)$')
where external_ref is null
  and source like 'DİM Grade 9, Russian sector, Variant A, 12 April 2026, Q%';

insert into questions as q
  (external_ref, source, subject_id, topic_id, subtopic, difficulty, type, prompt,
   options, correct_answer, paper_year, status, translations)
select v.external_ref, v.source, v.subject_id, v.topic_id, v.subtopic, v.difficulty, v.type, v.prompt,
       v.options, v.correct_answer, v.paper_year, v.status, v.translations
